package project.init.account.domain.req;import jakarta.validation.constraints.Email;import jakarta.validation.constraints.NotBlank;import jakarta.validation.constraints.Pattern;import jakarta.validation.constraints.Size;import lombok.Data;@Datapublic class RegisterReq {    @NotBlank(message = "Account code is required")    @Size(max = 8, message = "accountCode too long")    private String accountCode;    @NotBlank(message = "Account name is required")    private String accountName;    @NotBlank(message = "Email is required")    @Email(message = "Email is not valid")    private String accountEmail;    @Pattern(regexp = "^\\d{9,10}$", message = "Invalid mobile number")    private String accountMobile;    private String accountAddress;}